import{_ as o,l,o as e,c as i,v as t,p as n,x as r,d as T,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"HTTP/2 多路","description":"","frontmatter":{"title":"HTTP/2 多路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http2.md","filePath":"cs/http2.md","lastUpdated":1789023840000}'),p={name:"cs/http2.md"};function c(E,a,P,_,A,m){const s=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="http-2-多路" tabindex="-1">HTTP/2 多路 <a class="header-anchor" href="#http-2-多路" aria-label="Permalink to &quot;HTTP/2 多路&quot;">​</a></h1><div class="epigraph"><p>在一条加密连接上用流并行许多请求，避免 HTTP/1.1 里「一请求一连接」或队头阻塞在应用层的排队。</p><footer>—— 据 RFC 9113, HTTP/2；对照 RFC 9110 语义不变；Kurose and Ross</footer></div><p><a href="/cs/http-semantics">上一课</a>钉死方法与缓存头。本课不重写幂等。缺口是映射：HTTP/1.1 在一条连接上请求必须排成队，前一个响应没完，后一个出不去——这是应用层队头阻塞。HTTP/2 把帧编进流，多路复用同一条 TCP（通常再套 TLS）。本课不把 TLS 握手写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器为躲排队会开许多连接，挤拥塞窗口、加重握手。<a href="/cs/nagle-delayed-ack">Nagle 与延迟 ACK</a> 在多连接上各自为政。HTTP/2：二进制帧、流标识、优先级直觉、头部压缩。语义仍是 RFC 9110 的请求–响应。缺口是<strong>一条运输连接上的多请求</strong>，不是新方法。</p><p><span class="marginnote">TCP 字节流仍有传输层队头阻塞：丢一个段，所有流停。后课 QUIC 对照把流做到 UDP 上。本课只收到 HTTP/2。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>握手升级或 ALPN 选 h2。每个请求一个流，帧带流 ID 交错发送。窗口在连接与流两级做流控，避免一个大下载饿死别人。头部压缩减少重复头的字节。服务器推送是可选机制，本课不把它当默认成功故事。</p>',8)),(e(),n(h,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H1%5B%22HTTP%2F1.1%20%E6%8E%92%E9%98%9F%E6%88%96%E5%A4%9A%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20H2%5B%22%E4%B8%80%E6%9D%A1%E8%BF%9E%E6%8E%A5%E4%B8%8A%E5%A4%9A%E6%B5%81%22%5D%0A%20%20H2%20--%3E%20FR%5B%22%E5%B8%A6%E6%B5%81%20ID%20%E7%9A%84%E5%B8%A7%22%5D%0A%20%20FR%20--%3E%20SEM%5B%22%E6%96%B9%E6%B3%95%E8%AF%AD%E4%B9%89%E4%BB%8D%E6%98%AF%209110%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多路把「并行」从多条 <a href="/cs/tcp-handshake">TCP 握手</a> 收成一条连接上的调度，让 <a href="/cs/tcp-congestion">拥塞控制</a> 看到聚合流量。缓存与幂等不因帧格式改变。中间人若不能解析二进制，就当隧道；可见代理要理解 h2。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 HTTP/3 帧类型插进主干正文，不引入全部 SETTINGS 参数。信道保密与认证下一课 TLS 入口（网络课已排在 HTTP/2 之后）。</p><p>后课默认：并行请求可以共享一条 TCP。套上保密管道是 TLS 入口的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HTTP/2 用流多路，语义仍是 RFC 9110。</li><li>不消除 TCP 层队头阻塞。</li><li>TLS 入口下一课。</li><li>出处：RFC 9113；RFC 9110；Kurose and Ross。</li></ul>',7))])}const B=o(p,[["render",c]]);export{f as __pageData,B as default};
